#### **报表路由**
```python
from flask_weasyprint import HTML, render_pdf

@app.route('/generate_report', methods=['GET'])
@token_required
def generate_report():
    orders = get_orders()
    inventory = get_inventory()
    html_content = f'''
    <h1>Restaurant Management Report</h1>
    <h2>Orders</h2>
    <ul>
    {''.join([f'<li>Order #{order["id"]}: {order["items"]} - {order["status"]}</li>' for order in orders])}
    </ul>
    <h2>Inventory</h2>
    <ul>
    {''.join([f'<li>{item["name"]}: {item["quantity"]}</li>' for item in inventory])}
    </ul>
    '''
    return render_pdf(HTML(string=html_content))
```

