pub(in super::super) fn verify_local_provision(
    store: &ObjectStore,
    closure: &CapsuleClosure,
) -> Result<()> {
    let provision = provision::load(store, &closure.module_cid)?;
    if provision::capsule_cid(&provision) != closure.capsule_cid
        || provision::executable_cid(&provision) != closure.executable_cid
        || provision::script_cid(&provision) != closure.script_cid.as_deref()
    {
        bail!("foreign-process local provision does not match the capsule closure");
    }
    if let Some(path) = provision::executable_path_optional(&provision) {
        verify_local_artifact(
            path,
            MAX_EXECUTABLE_BYTES,
            "provisioned executable",
            "executable",
            &closure.executable_cid,
        )?;
    }
    if let Some(path) = provision::sandbox_executable_path_optional(&provision) {
        verify_local_artifact(
            path,
            MAX_EXECUTABLE_BYTES,
            "sandbox executable",
            "executable",
            &closure.executable_cid,
        )?;
        windows_provision::verify_read_execute(path)?;
    }
    verify_script(&provision, closure)?;
    if let Some(cid) = closure.os_support_executable_cid.as_deref() {
        super::super::os_support::verify_host(&closure.environment, cid)?;
    }
    if let Some(package_graph_cid) = closure.package_graph_cid.as_deref() {
        package_graph::verify_local_materialization(
            store,
            package_graph_cid,
            provision::sandbox_script_path(&provision)?,
        )?;
    }
    if let Some(runtime_support_cid) = closure.runtime_support_cid.as_deref() {
        let directory = provision::sandbox_script_path(&provision)?
            .parent()
            .ok_or_else(|| anyhow::anyhow!("sandbox runtime directory is unavailable"))?;
        super::super::runtime_support::verify_materialized(store, runtime_support_cid, directory)?;
    }
    Ok(())
}

fn verify_script(provisioned: &provision::LocalProvision, closure: &CapsuleClosure) -> Result<()> {
    let Some(script_cid) = closure.script_cid.as_deref() else {
        if provision::script_path(provisioned).is_some() {
            bail!("foreign-process local provision has an unbound script path");
        }
        return Ok(());
    };
    if let Some(original) = provision::script_path(provisioned) {
        verify_local_artifact(
            original,
            MAX_SCRIPT_BYTES,
            "provisioned script",
            "script",
            script_cid,
        )?;
    }
    let sandbox = provision::sandbox_script_path(provisioned)?;
    verify_local_artifact(
        sandbox,
        MAX_SCRIPT_BYTES,
        "sandbox script",
        "script",
        script_cid,
    )?;
    windows_provision::verify_read(sandbox)
}

fn verify_local_artifact(
    path: &std::path::Path,
    limit: usize,
    label: &str,
    role: &str,
    expected_cid: &str,
) -> Result<()> {
    let bytes = provision::read_artifact(path, limit, label)?;
    let cid = cid_for_bytes(&encode_value_node(&value::artifact_value(role, bytes))?);
    if cid != expected_cid {
        bail!("foreign-process local artifact does not match the capsule closure");
    }
    Ok(())
}

